set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const root='/var/lib/news-flow/qc-remaining27-all-20261122',registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:[...registry.allowedDomains,'api.biggo.com'],siteCooldown:false,maxWireRequests:4}),id='383d64f9-5e19-49f2-86cb-34d51c915679',report={at:new Date().toISOString(),checks:[]};try{for(const path of ['/news/'+id,'/news/detail?news_id='+id]){const url='https://api.biggo.com/api/v1/finance'+path+(path.includes('?')?'&':'?')+'region=us',p=await driver.get('qc27-biggo-read-detail',url,registry.sources.get('finance.biggo.com').config,[],{reviewFailed:true,taskRole:'publisher_dependency',headers:{Accept:'application/json'}}),o={url,error:p.error,statusCode:p.statusCode};if(!p.error&&p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));try{const data=JSON.parse(p.html);o.keys=Object.keys(data);o.preview=JSON.stringify(data).slice(0,1600);}catch{}}report.checks.push(o);console.log(JSON.stringify(o));if(p.statusCode===401||p.statusCode===403)break;}fs.writeFileSync(root+'/biggo-detail-controls.json',JSON.stringify(report,null,2));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-remaining27-all-20261122/biggo-detail-controls.json "$upload_dir/.qc27-biggo-detail-controls.json"
